// FrameTypeName returns a human-readable string name for the given frame type.
// This is useful for logging and debugging gRPC frame processing.
func FrameTypeName(t http2.FrameType) string {
	switch t {
	case http2.FrameData:
		return "DATA"
	case http2.FrameHeaders:
		return "HEADERS"
	case http2.FramePriority:
		return "PRIORITY"
	case http2.FrameRSTStream:
		return "RST_STREAM"
	case http2.FrameSettings:
		return "SETTINGS"
	case http2.FramePushPromise:
		return "PUSH_PROMISE"
	case http2.FramePing:
		return "PING"
	case http2.FrameGoAway:
		return "GOAWAY"
	case http2.FrameWindowUpdate:
		return "WINDOW_UPDATE"
	case http2.FrameContinuation:
		return "CONTINUATION"
	default:
		return fmt.Sprintf("UNKNOWN(%d)", t)
	}
}

// LogFrameDiagnostic returns a diagnostic string for a frame header.
// Format: "FrameType[StreamID=X, Flags=Y, Length=Z]"
// This helps with troubleshooting streaming issues and protocol debugging.
func LogFrameDiagnostic(fh http2.FrameHeader) string {
	return fmt.Sprintf("%s[StreamID=%d, Flags=0x%x, Length=%d]",
		FrameTypeName(fh.Type), fh.StreamID, fh.Flags, fh.Length)
}

