// WithUnaryOptions sets unary-specific options for the client.
func WithUnaryOptions(opts ...UnaryOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryOptions(%d options)", len(opts)))
		if o.UnaryOpts == nil {
			o.UnaryOpts = &client.UnaryOptions{}
		}
		for _, opt := range opts {
			opt.F(o.UnaryOpts)
		}
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout specifically for unary calls.
func WithUnaryRPCTimeout(d time.Duration) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%s)", d))
		if o.UnaryOpts == nil {
			o.UnaryOpts = &client.UnaryOptions{}
		}
		o.UnaryOpts.RPCTimeout = d
	}}
}

// WithUnaryMiddleware adds middleware specifically for unary RPC calls.
func WithUnaryMiddleware(mw endpoint.Middleware) Option {
	mwb := func(ctx context.Context) endpoint.Middleware {
		return mw
	}
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddleware(%+v)", utils.GetFuncName(mw)))
		if o.UnaryOpts == nil {
			o.UnaryOpts = &client.UnaryOptions{}
		}
		o.UnaryOpts.MWBs = append(o.UnaryOpts.MWBs, mwb)
	}}
}

// WithUnaryMiddlewareBuilder adds a context-dependent middleware builder for unary calls.
func WithUnaryMiddlewareBuilder(mwb endpoint.MiddlewareBuilder) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddlewareBuilder(%+v)", utils.GetFuncName(mwb)))
		if o.UnaryOpts == nil {
			o.UnaryOpts = &client.UnaryOptions{}
		}
		o.UnaryOpts.MWBs = append(o.UnaryOpts.MWBs, mwb)
	}}
}

