// Dump returns diagnostic information about the connection pool.
// It is panic-safe and returns JSON-serializable data.
func (p *connPool) Dump() interface{} {
	defer func() {
		if r := recover(); r != nil {
			// Panic recovery to ensure diagnostic calls don't crash the system
		}
	}()

	result := make(map[string]interface{})
	result["pool_size"] = p.size
	result["remote_service"] = p.remoteService

	// Collect connection information
	connections := make(map[string]interface{})
	p.conns.Range(func(key, value interface{}) bool {
		addr, ok := key.(string)
		if !ok {
			return true
		}
		trans, ok := value.(*transports)
		if !ok {
			return true
		}

		connInfo := make(map[string]interface{})
		connInfo["size"] = trans.size
		connInfo["index"] = atomic.LoadUint32(&trans.index)

		// Count active connections
		activeCount := 0
		for i := 0; i < int(trans.size); i++ {
			if trans.cliTransports[i] != nil {
				if isActive, ok := trans.cliTransports[i].(grpc.IsActive); ok && isActive.IsActive() {
					activeCount++
				}
			}
		}
		connInfo["active_count"] = activeCount
		connections[addr] = connInfo
		return true
	})
	result["connections"] = connections

	return result
}

